<div class="grid grid-2"><div class="card"><div style="display:flex;align-items:center;justify-content:space-between;gap:8px"><h3>Request details</h3><span class="badge <?=status_class((int)$r['status'])?>"><?=e(status_names()[$r['status']])?></span></div><p><strong><?=e($r['category_name'])?></strong></p><p class="muted"><?=nl2br(e($r['description']))?></p><hr style="border:0;border-top:1px solid var(--sd-border)"><p><small class="muted">Location</small><br><strong><?=e($r['location'])?></strong></p><p><small class="muted">Submitted</small><br><?=e(status_timestamp($r['created_at']))?></p><p><small class="muted">Assigned responder</small><br><?=e($r['provider_name']??'Awaiting assignment')?></p><?php $att=$pdo->prepare('SELECT * FROM attachments WHERE request_id=? ORDER BY id DESC LIMIT 1');$att->execute([$id]);$photo=$att->fetch();if($photo):?><p><small class="muted">Attached photo</small></p><img class="photo-preview" src="<?=BASE_URL?>/uploads/<?=e($photo['stored_name'])?>" alt="Issue photo"><?php endif;?></div>
